#!/usr/bin/env node
// Post-build script: extract inline <script> bodies from every HTML file in
// out/, compute their SHA-256 hashes, and write nginx/csp-hashes.conf.
//
// nginx then includes that file and interpolates $csp_script_hashes into the
// script-src directive of the enforcing Content-Security-Policy header, so
// the policy stays valid across builds without 'unsafe-inline'.
//
//   node scripts/gen-csp-hashes.mjs
//
// The generated file is committed so the production image (which copies
// nginx.conf and nginx/) is always self-consistent with the out/ it was built
// from. CI rebuilds it on every `npm run build` (via the postbuild hook).
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

const OUT_DIR = "out";
const OUT_CONF = join("nginx", "csp-hashes.conf");

/** Recursively collect all *.html paths under `dir`. */
function findHtmlFiles(dir) {
  const results = [];
  const walk = (current) => {
    for (const entry of readdirSync(current)) {
      const full = join(current, entry);
      if (statSync(full).isDirectory()) {
        walk(full);
      } else if (entry.endsWith(".html")) {
        results.push(full);
      }
    }
  };
  walk(dir);
  return results;
}

/**
 * Extract the text content of every inline <script> (no src attribute).
 * The regex is intentionally simple: Next's static export emits well-formed,
 * single-line inline scripts with no nested tags.
 */
function extractInlineScripts(html) {
  const scripts = [];
  // Negative lookahead: skip any <script> that has a src="..." attribute.
  const re = /<script(?![^>]*\bsrc=(?:'[^']*'|"[^"]*"|[^\s>]*))[^>]*>([^]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const body = m[1];
    if (body.trim().length > 0) {
      scripts.push(body);
    }
  }
  return scripts;
}

function sha256base64(text) {
  return createHash("sha256").update(text, "utf8").digest("base64");
}

// ---- main ----------------------------------------------------------------

let htmlFiles;
try {
  htmlFiles = findHtmlFiles(OUT_DIR);
} catch (err) {
  console.error(`[gen-csp-hashes] Failed to list HTML files: ${err.message}`);
  console.error("  Run `npm run build` first to generate out/.");
  process.exit(1);
}

if (htmlFiles.length === 0) {
  console.error(
    "[gen-csp-hashes] No HTML files found in out/. Run `npm run build` first."
  );
  process.exit(1);
}

const seen = new Set();
for (const file of htmlFiles) {
  const html = readFileSync(file, "utf8");
  for (const script of extractInlineScripts(html)) {
    seen.add(sha256base64(script));
  }
}

if (seen.size === 0) {
  console.error(
    "[gen-csp-hashes] No inline scripts found — the HTML output may have changed shape."
  );
  process.exit(1);
}

// Build the value for nginx's $csp_script_hashes variable:
// 'sha256-AAAA=' 'sha256-BBBB=' ...
const hashList = [...seen].map((h) => `'sha256-${h}'`).join(" ");

const conf = `# Generated by scripts/gen-csp-hashes.mjs — do not edit by hand.
# Re-run via \`npm run build\` (postbuild) or \`node scripts/gen-csp-hashes.mjs\`.
# Inline-script SHA-256 hashes for the Next.js static export in out/.
# These are set on the $csp_script_hashes variable and interpolated into the
# Content-Security-Policy script-src directive by nginx.conf.
set $csp_script_hashes "${hashList}";
`;

mkdirSync("nginx", { recursive: true });
writeFileSync(OUT_CONF, conf, "utf8");

console.log(
  `[gen-csp-hashes] wrote ${seen.size} hash(es) to ${OUT_CONF}`
);
for (const h of seen) {
  console.log(`  sha256-${h}`);
}
